9	/**
10	 * Assigns the owner's {@code bulkSignupWarning}: {@code true} when more than 80 owners had already
11	 * been created today, otherwise {@code false}. "Today" follows the same accumulation path as the
12	 * per-day create limit — owners whose adjusted business-day {@code registrationDate} equals today's
13	 * business day. Runs before the new owner is saved, so the count reflects only the owners that
14	 * existed before this create.
15	 */
16	public class AssignBulkSignupWarning {
17	
18	    private static final long BULK_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        LocalDate businessDay = BusinessDays.rollForward(LocalDate.now());
22	        long createdToday = ownerRepository.findAll().stream()
23	                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
24	                .count();
25	        owner.setBulkSignupWarning(createdToday > BULK_THRESHOLD);
26	    }
27	}
